BEGIN
  FOR r IN SELECT * FROM jsonb_to_recordset('[{"cid":"8dd4395c-420f-46f2-b7a3-1bf039267421","uid":"1330dbe9-cac5-4ddb-8a39-b55abf4c3072","n":1,"title":"الشعر التعليمي في عصر الضعف","old":"DADYOOM_DZ_SCIENCE_OFFICIAL_DETAIL","focus":"تمييز الشعر التعليمي من الشعر الوجداني","passage":"يُستخدم النظم أحيانًا لتقريب المعارف وحفظ القواعد، ويحتاج تحليل هذا الغرض إلى فحص المقصود من الترتيب الإيقاعي لا الاكتفاء بالقافية. مثال ضاديوم الأصلي أن طالبًا يضع قاعدة لغوية في جمل موزونة لتسهيل حفظها ثم يشرح حدود تطبيقها؛ ليس بيتًا تراثيًا.","question":"ما غاية نظم قاعدة دراسية في مثال الطالب؟","correct":"تيسير الحفظ مع توضيح القاعدة","writing":"بعد مراجعة النص المقرر بعنوان «الشعر التعليمي في عصر الضعف» من مصدر معتمد، استخرج شاهدًا صحيحًا وحلله لغويًا أو سرديًا، ثم اكتب مثالًا من إنشائك وميّز بين المصدرين. إن لم يتوفر النص فاكتب فقط تحليل المثال المستقل دون نسبة أقوال إلى المؤلف.","wrong":["الاعتماد على العنوان وحده","اختلاق اقتباس ونسبته للمؤلف","إلغاء سياق النص ومصدره"]},{"cid":"8dd4395c-420f-46f2-b7a3-1bf039267421","uid":"1330dbe9-cac5-4ddb-8a39-b55abf4c3072","n":2,"title":"النثر العلمي في عصر الضعف","old":"DADYOOM_DZ_SCIENCE_OFFICIAL_DETAIL","focus":"تمييز الشرح والتعليل في النثر العلمي","passage":"قد تعرض بعض المدونات القديمة تصنيفًا للمعلومات وملاحظة وتعليلًا وفق أدوات المعرفة في زمانها، ولا تُعامل كل نتيجة تاريخية بوصفها حقيقة علمية معاصرة. تدريب مستقل يقارن طالب فيه تفسيرًا قديمًا لظاهرة بمصدر حديث ويحدد منهج كل منهما.","question":"كيف نتعامل مع تفسير علمي تاريخي؟","correct":"نوثقه ونقارنه بالمعرفة الحالية دون إسقاط","writing":"بعد مراجعة النص المقرر بعنوان «النثر العلمي في عصر الضعف» من مصدر معتمد، استخرج شاهدًا صحيحًا وحلله لغويًا أو سرديًا، ثم اكتب مثالًا من إنشائك وميّز بين المصدرين. إن لم يتوفر النص فاكتب فقط تحليل المثال المستقل دون نسبة أقوال إلى المؤلف.","wrong":["الاعتماد على العنوان وحده","اختلاق اقتباس ونسبته للمؤلف","إلغاء سياق النص ومصدره"]},{"cid":"8dd4395c-420f-46f2-b7a3-1bf039267421","uid":"566d0d40-fa5a-49a0-b61e-2de3f82720f1","n":1,"title":"النزعة الإنسانية في الشعر المهجري","old":"DADYOOM_DZ_SCIENCE_OFFICIAL_DETAIL","focus":"قراءة قيم التعاطف والاغتراب في الشعر","passage":"يمكن أن تتناول نصوص المهجر تجارب البعد والتعاطف والمشاركة الإنسانية بأشكال متعددة؛ يحتاج تعيين موقف شاعر إلى نص صحيح النسبة. نموذج مستقل يكتب فيه مسافر رسالة تقدير لأناس ساعدوه رغم اختلاف اللغة، وهو نثر تدريبي لا شعر مهجري.","question":"ما السلوك الذي يُظهر التعاطف في المثال؟","correct":"تقدير المساعدة رغم اختلاف اللغة","writing":"بعد مراجعة النص المقرر بعنوان «النزعة الإنسانية في الشعر المهجري» من مصدر معتمد، استخرج شاهدًا صحيحًا وحلله لغويًا أو سرديًا، ثم اكتب مثالًا من إنشائك وميّز بين المصدرين. إن لم يتوفر النص فاكتب فقط تحليل المثال المستقل دون نسبة أقوال إلى المؤلف.","wrong":["الاعتماد على العنوان وحده","اختلاق اقتباس ونسبته للمؤلف","إلغاء سياق النص ومصدره"]},{"cid":"8dd4395c-420f-46f2-b7a3-1bf039267421","uid":"566d0d40-fa5a-49a0-b61e-2de3f82720f1","n":2,"title":"شعر النهضة وموقفه من حضارة الغرب","old":"DADYOOM_DZ_SCIENCE_OFFICIAL_DETAIL","focus":"تحليل الحجج المتعددة بشأن التفاعل الثقافي","passage":"لا يصح تلخيص الشعر النهضوي في تأييد مطلق أو رفض مطلق لتجربة حضارية، فقد تختلف النصوص والأزمنة. في حوار من تأليف ضاديوم يقترح متعلم الاستفادة من وسيلة تقنية مع حماية اللغة والخصوصية، فيوازن المنافع والتحفظات.","question":"ما الذي يجعل الموقف الثقافي متوازنًا؟","correct":"تقييم المنافع والتحديات بدليل","writing":"بعد مراجعة النص المقرر بعنوان «شعر النهضة وموقفه من حضارة الغرب» من مصدر معتمد، استخرج شاهدًا صحيحًا وحلله لغويًا أو سرديًا، ثم اكتب مثالًا من إنشائك وميّز بين المصدرين. إن لم يتوفر النص فاكتب فقط تحليل المثال المستقل دون نسبة أقوال إلى المؤلف.","wrong":["الاعتماد على العنوان وحده","اختلاق اقتباس ونسبته للمؤلف","إلغاء سياق النص ومصدره"]},{"cid":"8dd4395c-420f-46f2-b7a3-1bf039267421","uid":"566d0d40-fa5a-49a0-b61e-2de3f82720f1","n":3,"title":"الشعر الملتزم وقضايا التحرر","old":"DADYOOM_DZ_SCIENCE_OFFICIAL_DETAIL","focus":"تفسير موقف المتكلم من الكرامة والحرية","passage":"قد يناقش الشعر الملتزم المسؤولية العامة والتحرر والحقوق، لكنه لا يحل محل الوثيقة التاريخية. التحليل يحدد صوت المتكلم والمخاطب والصور الدالة على الموقف. في مثال أصلي يناشد راو أن تُتاح فرصة التعلم للجميع دون تمييز، ولا يمثل نصًا منسوبًا.","question":"ما القرينة على الالتزام بقضية عامة؟","correct":"تعليل مطلب يخص حقوق الآخرين","writing":"بعد مراجعة النص المقرر بعنوان «الشعر الملتزم وقضايا التحرر» من مصدر معتمد، استخرج شاهدًا صحيحًا وحلله لغويًا أو سرديًا، ثم اكتب مثالًا من إنشائك وميّز بين المصدرين. إن لم يتوفر النص فاكتب فقط تحليل المثال المستقل دون نسبة أقوال إلى المؤلف.","wrong":["الاعتماد على العنوان وحده","اختلاق اقتباس ونسبته للمؤلف","إلغاء سياق النص ومصدره"]},{"cid":"8dd4395c-420f-46f2-b7a3-1bf039267421","uid":"566d0d40-fa5a-49a0-b61e-2de3f82720f1","n":4,"title":"نكبة فلسطين في الشعر العربي","old":"DADYOOM_DZ_SCIENCE_OFFICIAL_DETAIL","focus":"تحليل الذاكرة والفقد دون اختلاق الشواهد","passage":"تستلزم دراسة نكبة فلسطين في الأدب التحقق من التاريخ وأصحاب النصوص والتمييز بين شهادة الشاعر والصور الرمزية. مشهد مستقل تصف فيه أسرة ذكريات منزل فقدته وتحتفظ بمفتاح قديم؛ الغرض التدريب على دلالات المكان والذاكرة دون نسبته لقصيدة تاريخية.","question":"ما دلالة المفتاح في المثال المستقل؟","correct":"استمرار الذاكرة وعلاقة الأسرة بالمكان","writing":"بعد مراجعة النص المقرر بعنوان «نكبة فلسطين في الشعر العربي» من مصدر معتمد، استخرج شاهدًا صحيحًا وحلله لغويًا أو سرديًا، ثم اكتب مثالًا من إنشائك وميّز بين المصدرين. إن لم يتوفر النص فاكتب فقط تحليل المثال المستقل دون نسبة أقوال إلى المؤلف.","wrong":["الاعتماد على العنوان وحده","اختلاق اقتباس ونسبته للمؤلف","إلغاء سياق النص ومصدره"]},{"cid":"8dd4395c-420f-46f2-b7a3-1bf039267421","uid":"566d0d40-fa5a-49a0-b61e-2de3f82720f1","n":5,"title":"الثورة التحريرية الجزائرية في الشعر العربي","old":"DADYOOM_DZ_SCIENCE_OFFICIAL_DETAIL","focus":"فصل السجل التاريخي عن الصوت الشعري","passage":"لتحليل الشعر المرتبط بالثورة الجزائرية نثبت النص والشاعر والسياق قبل تفسير الصور والأفعال، ونميز بين الوقائع التاريخية والأسلوب المجازي. نموذج مستقل يصف مجموعة تستعيد ذكرى استقلالها في معرض للوثائق، ولا يكرر نصًا أصليًا.","question":"ما شرط ربط صورة شعرية بحدث تاريخي؟","correct":"توثيق النص والحدث وتحليل المجاز","writing":"بعد مراجعة النص المقرر بعنوان «الثورة التحريرية الجزائرية في الشعر العربي» من مصدر معتمد، استخرج شاهدًا صحيحًا وحلله لغويًا أو سرديًا، ثم اكتب مثالًا من إنشائك وميّز بين المصدرين. إن لم يتوفر النص فاكتب فقط تحليل المثال المستقل دون نسبة أقوال إلى المؤلف.","wrong":["الاعتماد على العنوان وحده","اختلاق اقتباس ونسبته للمؤلف","إلغاء سياق النص ومصدره"]},{"cid":"8dd4395c-420f-46f2-b7a3-1bf039267421","uid":"566d0d40-fa5a-49a0-b61e-2de3f82720f1","n":6,"title":"الشعر الاجتماعي في العصر الحديث","old":"DADYOOM_DZ_SCIENCE_OFFICIAL_DETAIL","focus":"قراءة قضايا المجتمع بأدلة لغوية","passage":"قد يناقش الشعر الحديث ظروف العمل أو التعليم أو العدالة أو العلاقات الاجتماعية، لكن وجود قضية لا يعني بالضرورة تعبير الشاعر عن حلول عملية. في وصف أصلي يلاحظ راو بُعد مدرسة عن بعض الطلبة ويقترح مناقشة النقل؛ يفرق الناقد بين الوصف والموقف.","question":"ما الفرق بين الوصف والدعوى في النص الاجتماعي؟","correct":"الوصف يحدد الملاحظة والدعوى تتخذ موقفًا","writing":"بعد مراجعة النص المقرر بعنوان «الشعر الاجتماعي في العصر الحديث» من مصدر معتمد، استخرج شاهدًا صحيحًا وحلله لغويًا أو سرديًا، ثم اكتب مثالًا من إنشائك وميّز بين المصدرين. إن لم يتوفر النص فاكتب فقط تحليل المثال المستقل دون نسبة أقوال إلى المؤلف.","wrong":["الاعتماد على العنوان وحده","اختلاق اقتباس ونسبته للمؤلف","إلغاء سياق النص ومصدره"]},{"cid":"8dd4395c-420f-46f2-b7a3-1bf039267421","uid":"566d0d40-fa5a-49a0-b61e-2de3f82720f1","n":7,"title":"مظاهر ازدهار الكتابة الفنية - المقال","old":"DADYOOM_DZ_SCIENCE_OFFICIAL_DETAIL","focus":"المقال بين الأطروحة والحجة والأسلوب","passage":"تقوم المقالة الفنية على فكرة واضحة وترابط الفقرات وانتقاء أمثلة تخدم الغرض وقد تسمح بصوت شخصي دون التفريط في التعليل. نموذج مستقل: يكتب طالب عن القراءة ثم يدعم رأيه بتجربة ونقطة قابلة للاعتراض، ولا ينسبه إلى مؤلف تاريخي.","question":"ما الذي يقوي مقالة رأي؟","correct":"حجة موضحة بمثال واعتراض محتمل","writing":"بعد مراجعة النص المقرر بعنوان «مظاهر ازدهار الكتابة الفنية - المقال» من مصدر معتمد، استخرج شاهدًا صحيحًا وحلله لغويًا أو سرديًا، ثم اكتب مثالًا من إنشائك وميّز بين المصدرين. إن لم يتوفر النص فاكتب فقط تحليل المثال المستقل دون نسبة أقوال إلى المؤلف.","wrong":["الاعتماد على العنوان وحده","اختلاق اقتباس ونسبته للمؤلف","إلغاء سياق النص ومصدره"]},{"cid":"8dd4395c-420f-46f2-b7a3-1bf039267421","uid":"566d0d40-fa5a-49a0-b61e-2de3f82720f1","n":8,"title":"القصة القصيرة في الجزائر","old":"DADYOOM_DZ_SCIENCE_OFFICIAL_DETAIL","focus":"تحليل الحدث والشخصية والبنية القصصية","passage":"تتعدد اتجاهات القصة الجزائرية ولا يلزم منها حبكة واحدة؛ يحتاج التحليل نصًا محددًا وشاهدًا على العقدة والتحول. في قصة مستقلة يخطئ طالب في عنوان رسالة، ثم يكتشف الخطأ ويحاول إصلاحه قبل الموعد؛ تفسر النهاية قرار الشخصية.","question":"ما الذي يؤدي إلى تحوّل الحدث في المثال؟","correct":"اكتشاف الخطأ ومحاولة تصحيحه","writing":"بعد مراجعة النص المقرر بعنوان «القصة القصيرة في الجزائر» من مصدر معتمد، استخرج شاهدًا صحيحًا وحلله لغويًا أو سرديًا، ثم اكتب مثالًا من إنشائك وميّز بين المصدرين. إن لم يتوفر النص فاكتب فقط تحليل المثال المستقل دون نسبة أقوال إلى المؤلف.","wrong":["الاعتماد على العنوان وحده","اختلاق اقتباس ونسبته للمؤلف","إلغاء سياق النص ومصدره"]},{"cid":"8dd4395c-420f-46f2-b7a3-1bf039267421","uid":"566d0d40-fa5a-49a0-b61e-2de3f82720f1","n":9,"title":"الفن المسرحي في المشرق","old":"DADYOOM_DZ_SCIENCE_OFFICIAL_DETAIL","focus":"تمييز الحوار والصراع والإرشاد المسرحي","passage":"يبني المسرح أثره عبر الحوار والفعل ومواجهة مواقف متباينة، وقد تضيف الإرشادات المشهدية حركة وإضاءة لا يمكن فهمها من كلام الشخصية وحده. مثال مستقل يتحاور عضوان بشأن تنظيم معرض ويغير أحدهما اقتراحه بعد دليل جديد.","question":"ما العنصر الذي يحرك المشهد المسرحي؟","correct":"الحوار وتغير القرار نتيجة صراع واضح","writing":"بعد مراجعة النص المقرر بعنوان «الفن المسرحي في المشرق» من مصدر معتمد، استخرج شاهدًا صحيحًا وحلله لغويًا أو سرديًا، ثم اكتب مثالًا من إنشائك وميّز بين المصدرين. إن لم يتوفر النص فاكتب فقط تحليل المثال المستقل دون نسبة أقوال إلى المؤلف.","wrong":["الاعتماد على العنوان وحده","اختلاق اقتباس ونسبته للمؤلف","إلغاء سياق النص ومصدره"]},{"cid":"8dd4395c-420f-46f2-b7a3-1bf039267421","uid":"566d0d40-fa5a-49a0-b61e-2de3f82720f1","n":10,"title":"الأدب المسرحي الجزائري","old":"DADYOOM_DZ_SCIENCE_OFFICIAL_DETAIL","focus":"تحليل الشخصية والسياق في نص مسرحي","passage":"تحتاج دراسة المسرح الجزائري إلى نصوص وأسماء وأزمنة موثقة، ويُحدد الأداء الدرامي من أفعال الشخصيات والتوتر وتحول المشهد. تدريب من ضاديوم: تناقش شخصيتان قرارًا لجمعية ثقافية مع الحفاظ على اختلاف الرأيين؛ لا يمثّل مسرحية منشورة.","question":"ما الدليل على تطور شخصية درامية؟","correct":"تغير موقفها بعد حدث أو حجة","writing":"بعد مراجعة النص المقرر بعنوان «الأدب المسرحي الجزائري» من مصدر معتمد، استخرج شاهدًا صحيحًا وحلله لغويًا أو سرديًا، ثم اكتب مثالًا من إنشائك وميّز بين المصدرين. إن لم يتوفر النص فاكتب فقط تحليل المثال المستقل دون نسبة أقوال إلى المؤلف.","wrong":["الاعتماد على العنوان وحده","اختلاق اقتباس ونسبته للمؤلف","إلغاء سياق النص ومصدره"]},{"cid":"c02be22c-60e1-4541-9365-ce42d62ab66b","uid":"f86d3d9d-11b0-4c62-b631-e3e2e72d7709","n":1,"title":"لالة فاطمة نسومر المرأة الصقر - إدريس قرقوة","old":"DADYOOM_DZ_G12_LANGUAGES_OFFICIAL","focus":"الفصل بين الشخصية التاريخية وتمثيلها المسرحي","passage":"تقتضي قراءة عمل مسرحي يتناول شخصية تاريخية مثل لالة فاطمة نسومر التفريق بين الأحداث المثبتة وخيارات الكاتب التخيلية في الحوار والصراع. لا يجوز ابتكار كلام ثم نسبته إلى النص أو الشخصية، لذا يستعمل التدريب وصفًا مستقلًا لعرض ومراجعة مصادره.","question":"ما الفرق بين الحوار المسرحي والتوثيق التاريخي؟","correct":"الحوار بناء فني لا يثبت وقوع الكلمات نفسها","writing":"بعد مراجعة النص المقرر بعنوان «لالة فاطمة نسومر المرأة الصقر - إدريس قرقوة» من مصدر معتمد، استخرج شاهدًا صحيحًا وحلله لغويًا أو سرديًا، ثم اكتب مثالًا من إنشائك وميّز بين المصدرين. إن لم يتوفر النص فاكتب فقط تحليل المثال المستقل دون نسبة أقوال إلى المؤلف.","wrong":["الاعتماد على العنوان وحده","اختلاق اقتباس ونسبته للمؤلف","إلغاء سياق النص ومصدره"]},{"cid":"c02be22c-60e1-4541-9365-ce42d62ab66b","uid":"f86d3d9d-11b0-4c62-b631-e3e2e72d7709","n":2,"title":"من مسرحية المغص - أحمد بو دشيشة","old":"DADYOOM_DZ_G12_LANGUAGES_OFFICIAL","focus":"تحليل المفارقة والحوار دون اختلاق النص","passage":"عنوان مسرحية لا يكفي لتحديد شخصياتها أو دلالة النهاية؛ يحتاج المتعلم النص المعتمد ويحدد مَن يتكلم ومن يستجيب وكيف تنشأ المفارقة. في مشهد مستقل يكرر مسؤول وعدًا ثم ينسى تنفيذ المطلوب، فتظهر مفارقة بين القول والفعل.","question":"ما المفارقة في المثال التدريبي؟","correct":"التناقض بين الوعد وتنفيذ العمل","writing":"بعد مراجعة النص المقرر بعنوان «من مسرحية المغص - أحمد بو دشيشة» من مصدر معتمد، استخرج شاهدًا صحيحًا وحلله لغويًا أو سرديًا، ثم اكتب مثالًا من إنشائك وميّز بين المصدرين. إن لم يتوفر النص فاكتب فقط تحليل المثال المستقل دون نسبة أقوال إلى المؤلف.","wrong":["الاعتماد على العنوان وحده","اختلاق اقتباس ونسبته للمؤلف","إلغاء سياق النص ومصدره"]},{"cid":"c02be22c-60e1-4541-9365-ce42d62ab66b","uid":"9710a08c-40a4-4d75-a37c-a5586f2bcb54","n":1,"title":"أغنيات للألم - نازك الملائكة","old":"DADYOOM_DZ_G12_LANGUAGES_OFFICIAL","focus":"تحليل المعجم الوجداني والإيقاع في قصيدة موثقة","passage":"لا يمكن تعيين صور قصيدة لنازك الملائكة من عنوانها؛ يجب قراءة نصها الصحيح وملاحظة تكرار الألفاظ وإيقاع المقطع ودور الصورة. نموذج مستقل يصف متكلمًا يراقب مقعدًا خاليًا ويشعر بفقد صديق، ولا يمثل بيتًا من القصيدة.","question":"ما الذي يدعم تفسير عاطفة القصيدة؟","correct":"شاهد من المعجم والإيقاع والصورة","writing":"بعد مراجعة النص المقرر بعنوان «أغنيات للألم - نازك الملائكة» من مصدر معتمد، استخرج شاهدًا صحيحًا وحلله لغويًا أو سرديًا، ثم اكتب مثالًا من إنشائك وميّز بين المصدرين. إن لم يتوفر النص فاكتب فقط تحليل المثال المستقل دون نسبة أقوال إلى المؤلف.","wrong":["الاعتماد على العنوان وحده","اختلاق اقتباس ونسبته للمؤلف","إلغاء سياق النص ومصدره"]},{"cid":"c02be22c-60e1-4541-9365-ce42d62ab66b","uid":"9710a08c-40a4-4d75-a37c-a5586f2bcb54","n":2,"title":"أحزان الغربة","old":"DADYOOM_DZ_G12_LANGUAGES_OFFICIAL","focus":"قراءة الحنين وصورة المكان في نص الغربة","passage":"يمكن تصوير الاغتراب من خلال المسافة والذاكرة والمقارنة بين مكانين، لكنه لا يعني أن كل متكلم شعري يروي سيرة الكاتب حرفيًا. تدريب أصلي: يعيد مسافر فتح صورة الحي القديم بعد انتقاله إلى بلد جديد.","question":"ما القرينة على الحنين في المثال؟","correct":"تأمل صورة الحي القديم بعد الرحيل","writing":"بعد مراجعة النص المقرر بعنوان «أحزان الغربة» من مصدر معتمد، استخرج شاهدًا صحيحًا وحلله لغويًا أو سرديًا، ثم اكتب مثالًا من إنشائك وميّز بين المصدرين. إن لم يتوفر النص فاكتب فقط تحليل المثال المستقل دون نسبة أقوال إلى المؤلف.","wrong":["الاعتماد على العنوان وحده","اختلاق اقتباس ونسبته للمؤلف","إلغاء سياق النص ومصدره"]},{"cid":"c02be22c-60e1-4541-9365-ce42d62ab66b","uid":"0c586683-a2aa-4c2a-9c25-1401cc6641c1","n":1,"title":"الإنسان الكبير - محمد صالح باوية","old":"DADYOOM_DZ_G12_LANGUAGES_OFFICIAL","focus":"بناء قراءة للنص دون نسبة صور غير موثقة","passage":"يستلزم تحليل قصيدة «الإنسان الكبير» الرجوع إلى نص محمد صالح باوية المقرر قبل تحديد المخاطب أو معنى «الكبير». تدريب مستقل يقارن بين قوة المكانة الاجتماعية وقيمة المسؤولية تجاه الآخرين؛ لا يمثل قول الشاعر.","question":"ما المنهج الصحيح لفهم وصف «الكبير»؟","correct":"تفسيره من الأبيات الموثقة وسياقها","writing":"بعد مراجعة النص المقرر بعنوان «الإنسان الكبير - محمد صالح باوية» من مصدر معتمد، استخرج شاهدًا صحيحًا وحلله لغويًا أو سرديًا، ثم اكتب مثالًا من إنشائك وميّز بين المصدرين. إن لم يتوفر النص فاكتب فقط تحليل المثال المستقل دون نسبة أقوال إلى المؤلف.","wrong":["الاعتماد على العنوان وحده","اختلاق اقتباس ونسبته للمؤلف","إلغاء سياق النص ومصدره"]},{"cid":"c02be22c-60e1-4541-9365-ce42d62ab66b","uid":"0c586683-a2aa-4c2a-9c25-1401cc6641c1","n":2,"title":"جميلة - شفيق الكمالي","old":"DADYOOM_DZ_G12_LANGUAGES_OFFICIAL","focus":"تمييز الرمز من الشخصية الواقعية في القصيدة","passage":"قد يشير الاسم الشخصي في القصيدة إلى شخصية أو رمز، ولا يحسم العنوان وحده مدلوله أو زمن الحدث. يحتاج الدارس نص شفيق الكمالي الحقيقي؛ المثال المستقل يحكي عن شخصية تدافع عن الحق بأسلوب سلمي، دون نسبته للشاعر.","question":"ما الذي يحدد إن كان الاسم رمزًا شعريًا؟","correct":"قرائن الأبيات والسياق والمخاطب","writing":"بعد مراجعة النص المقرر بعنوان «جميلة - شفيق الكمالي» من مصدر معتمد، استخرج شاهدًا صحيحًا وحلله لغويًا أو سرديًا، ثم اكتب مثالًا من إنشائك وميّز بين المصدرين. إن لم يتوفر النص فاكتب فقط تحليل المثال المستقل دون نسبة أقوال إلى المؤلف.","wrong":["الاعتماد على العنوان وحده","اختلاق اقتباس ونسبته للمؤلف","إلغاء سياق النص ومصدره"]},{"cid":"c02be22c-60e1-4541-9365-ce42d62ab66b","uid":"3441a0a1-4e27-4f30-8afe-32857ff14827","n":1,"title":"من مسرحية شهرزاد - توفيق الحكيم","old":"DADYOOM_DZ_G12_LANGUAGES_OFFICIAL","focus":"تفسير الشخصية التراثية في نص مسرحي حديث","passage":"قد تعيد مسرحية حديثة بناء شخصية تراثية عبر حوار جديد وصراع فلسفي؛ لا يجوز نسبة تفاصيل هذا البناء إلى الحكاية القديمة دون مقارنة نصية. نموذج مستقل يضع شخصية أمام سؤال بين الحقيقة والخيال في حوار غير منسوب.","question":"كيف نميز توظيف التراث عن نسخه حرفيًا؟","correct":"مقارنة الحوار الحديث بالمصدر التراثي","writing":"بعد مراجعة النص المقرر بعنوان «من مسرحية شهرزاد - توفيق الحكيم» من مصدر معتمد، استخرج شاهدًا صحيحًا وحلله لغويًا أو سرديًا، ثم اكتب مثالًا من إنشائك وميّز بين المصدرين. إن لم يتوفر النص فاكتب فقط تحليل المثال المستقل دون نسبة أقوال إلى المؤلف.","wrong":["الاعتماد على العنوان وحده","اختلاق اقتباس ونسبته للمؤلف","إلغاء سياق النص ومصدره"]},{"cid":"c02be22c-60e1-4541-9365-ce42d62ab66b","uid":"3441a0a1-4e27-4f30-8afe-32857ff14827","n":2,"title":"كابوس في الظهيرة - حسين عبد الخضر","old":"DADYOOM_DZ_G12_LANGUAGES_OFFICIAL","focus":"تحليل التوتر الدرامي والتدرج في المشهد","passage":"عنوان «كابوس في الظهيرة» لا يكشف وحده عن عقدة العمل أو شخصياته؛ يفحص القارئ نص حسين عبد الخضر الموثق لتمييز الواقع من الرمز وطريقة تصاعد الموقف. مثال مستقل يحكي سوء فهم يزول بتوضيح رسالة.","question":"ما الذي يحدد نقطة تحول المشهد؟","correct":"حدث يغير فهم الشخصية أو قرارها","writing":"بعد مراجعة النص المقرر بعنوان «كابوس في الظهيرة - حسين عبد الخضر» من مصدر معتمد، استخرج شاهدًا صحيحًا وحلله لغويًا أو سرديًا، ثم اكتب مثالًا من إنشائك وميّز بين المصدرين. إن لم يتوفر النص فاكتب فقط تحليل المثال المستقل دون نسبة أقوال إلى المؤلف.","wrong":["الاعتماد على العنوان وحده","اختلاق اقتباس ونسبته للمؤلف","إلغاء سياق النص ومصدره"]},{"cid":"c02be22c-60e1-4541-9365-ce42d62ab66b","uid":"bbd0324b-f780-43b5-9130-eb57a51ebfa0","n":1,"title":"الجرح والأمل - زليخة السعودي","old":"DADYOOM_DZ_G12_LANGUAGES_OFFICIAL","focus":"قراءة تعارض الانكسار والتطلع في القصة","passage":"العنوان يجمع معنيين متوترين، لكن تحديد كيفية ظهورهما في قصة زليخة السعودي يستلزم النص الأصلي. مشهد مستقل: يخفق متعلم في تجربة ثم يعيدها بتوجيه جديد؛ يوضح تعاقب الإحباط والأمل من دون نسبته للقصة.","question":"ما عنصر التحول في المثال؟","correct":"العودة إلى التجربة بعد الإخفاق","writing":"بعد مراجعة النص المقرر بعنوان «الجرح والأمل - زليخة السعودي» من مصدر معتمد، استخرج شاهدًا صحيحًا وحلله لغويًا أو سرديًا، ثم اكتب مثالًا من إنشائك وميّز بين المصدرين. إن لم يتوفر النص فاكتب فقط تحليل المثال المستقل دون نسبة أقوال إلى المؤلف.","wrong":["الاعتماد على العنوان وحده","اختلاق اقتباس ونسبته للمؤلف","إلغاء سياق النص ومصدره"]},{"cid":"c02be22c-60e1-4541-9365-ce42d62ab66b","uid":"bbd0324b-f780-43b5-9130-eb57a51ebfa0","n":2,"title":"الطريق إلى قرية الطوب - محمد شنوفي","old":"DADYOOM_DZ_G12_LANGUAGES_OFFICIAL","focus":"تحليل المكان والرحلة والعقدة السردية","passage":"لا يمكن افتراض أحداث قصة من عنوان طريق أو قرية؛ يحتاج القارئ إلى النسخة الأصلية، ويحلل وظيفة المكان والعقبات ونقطة الوصول في البناء. مثال تدريبي: يغير مسافر مساره بعد اكتشاف طريق مغلق ويتعلم طلب معلومات موثوقة.","question":"ما الذي صنع العقدة في مشهد المسافر؟","correct":"انغلاق الطريق والحاجة إلى بديل","writing":"بعد مراجعة النص المقرر بعنوان «الطريق إلى قرية الطوب - محمد شنوفي» من مصدر معتمد، استخرج شاهدًا صحيحًا وحلله لغويًا أو سرديًا، ثم اكتب مثالًا من إنشائك وميّز بين المصدرين. إن لم يتوفر النص فاكتب فقط تحليل المثال المستقل دون نسبة أقوال إلى المؤلف.","wrong":["الاعتماد على العنوان وحده","اختلاق اقتباس ونسبته للمؤلف","إلغاء سياق النص ومصدره"]},{"cid":"c02be22c-60e1-4541-9365-ce42d62ab66b","uid":"fed3efca-fed4-48a7-acee-2037a80e73f5","n":1,"title":"خواص القمر وتأثيراته - القزويني","old":"DADYOOM_DZ_G12_LANGUAGES_OFFICIAL","focus":"تمييز التصورات العلمية التراثية من المعرفة التجريبية الحديثة","passage":"تقتضي قراءة نص علمي منسوب للقزويني توثيق العبارة وفهم مناهج عصره، وعدم تقديم كل تفسير تاريخي بوصفه حقيقة علمية حالية. تمرين مستقل: يقارن طالب تفسيرًا تراثيًا لحركة جرم سماوي ببيان فلكي معاصر موثق.","question":"ما الطريقة المناسبة لتقييم دعوى علمية قديمة؟","correct":"توثيقها ومقارنتها بالمعرفة المبنية على الدليل","writing":"بعد مراجعة النص المقرر بعنوان «خواص القمر وتأثيراته - القزويني» من مصدر معتمد، استخرج شاهدًا صحيحًا وحلله لغويًا أو سرديًا، ثم اكتب مثالًا من إنشائك وميّز بين المصدرين. إن لم يتوفر النص فاكتب فقط تحليل المثال المستقل دون نسبة أقوال إلى المؤلف.","wrong":["الاعتماد على العنوان وحده","اختلاق اقتباس ونسبته للمؤلف","إلغاء سياق النص ومصدره"]},{"cid":"c02be22c-60e1-4541-9365-ce42d62ab66b","uid":"fed3efca-fed4-48a7-acee-2037a80e73f5","n":2,"title":"علم التاريخ - ابن خلدون","old":"DADYOOM_DZ_G12_LANGUAGES_OFFICIAL","focus":"فحص الخبر التاريخي والتعليل الاجتماعي","passage":"عند دراسة أفكار ابن خلدون يرجع الطالب إلى نص محقق كي يميز بين تعريف الخبر واستدلال الباحث وقرائن قبوله، ولا تُنسب له عبارات من إنشاء ضاديوم. مثال مستقل يقارن قارئ روايتين لحدث ويبحث عن قرينة تؤيد كلًا منهما.","question":"ما أساس نقد الرواية التاريخية في التمرين؟","correct":"الموازنة بين المصادر والقرائن","writing":"بعد مراجعة النص المقرر بعنوان «علم التاريخ - ابن خلدون» من مصدر معتمد، استخرج شاهدًا صحيحًا وحلله لغويًا أو سرديًا، ثم اكتب مثالًا من إنشائك وميّز بين المصدرين. إن لم يتوفر النص فاكتب فقط تحليل المثال المستقل دون نسبة أقوال إلى المؤلف.","wrong":["الاعتماد على العنوان وحده","اختلاق اقتباس ونسبته للمؤلف","إلغاء سياق النص ومصدره"]},{"cid":"c02be22c-60e1-4541-9365-ce42d62ab66b","uid":"becc37be-ad81-4668-8288-f73acd3be865","n":1,"title":"أنا - إيليا أبو ماضي","old":"DADYOOM_DZ_G12_LANGUAGES_OFFICIAL","focus":"تحليل ضمير المتكلم ومسألة الهوية","passage":"لا يعني تكرار «أنا» أن القصيدة سيرة ذاتية مباشرة؛ تُفهم هوية المتكلم من النص والضمائر والأسئلة والصور. يحتاج نص إيليا أبو ماضي الحقيقي قبل نسبة أي صورة إليه. مثال مستقل متحدث يسأل عن دوره في مجتمع جديد.","question":"ما الذي يحدد صورة الذات في القصيدة؟","correct":"سياق ضمير المتكلم والصور والقرائن","writing":"بعد مراجعة النص المقرر بعنوان «أنا - إيليا أبو ماضي» من مصدر معتمد، استخرج شاهدًا صحيحًا وحلله لغويًا أو سرديًا، ثم اكتب مثالًا من إنشائك وميّز بين المصدرين. إن لم يتوفر النص فاكتب فقط تحليل المثال المستقل دون نسبة أقوال إلى المؤلف.","wrong":["الاعتماد على العنوان وحده","اختلاق اقتباس ونسبته للمؤلف","إلغاء سياق النص ومصدره"]},{"cid":"c02be22c-60e1-4541-9365-ce42d62ab66b","uid":"becc37be-ad81-4668-8288-f73acd3be865","n":2,"title":"هنا وهناك - القروي","old":"DADYOOM_DZ_G12_LANGUAGES_OFFICIAL","focus":"دراسة المقابلة المكانية وأثرها الوجداني","passage":"تخلق عبارتا «هنا» و«هناك» احتمال مقابلة مكانية أو نفسية، لكن معناهما المحدد يتوقف على النص الصحيح المنسوب إلى القروي. في مثال مستقل يقارن مغترب بين شتاء بلدين ويربط أحد المكانين بطفولته.","question":"ما الأثر الذي تُحدثه المقابلة في المثال؟","correct":"إبراز اختلاف المكان وعلاقته بالذاكرة","writing":"بعد مراجعة النص المقرر بعنوان «هنا وهناك - القروي» من مصدر معتمد، استخرج شاهدًا صحيحًا وحلله لغويًا أو سرديًا، ثم اكتب مثالًا من إنشائك وميّز بين المصدرين. إن لم يتوفر النص فاكتب فقط تحليل المثال المستقل دون نسبة أقوال إلى المؤلف.","wrong":["الاعتماد على العنوان وحده","اختلاق اقتباس ونسبته للمؤلف","إلغاء سياق النص ومصدره"]},{"cid":"c02be22c-60e1-4541-9365-ce42d62ab66b","uid":"2a01342e-f419-4f2a-a727-7dc0c1bd3e30","n":1,"title":"أبو تمام - صلاح عبد الصبور","old":"DADYOOM_DZ_G12_LANGUAGES_OFFICIAL","focus":"فهم استدعاء الشاعر القديم في نص حديث","passage":"قد يكون حضور اسم أبي تمام في عمل حديث استدعاءً رمزيًا أو حوارًا مع التراث، ولا تثبت النية من العنوان وحده. يتطلب فهم نص صلاح عبد الصبور المقرر فصل موقف المتكلم الحديث من صورة الشخصية التاريخية.","question":"ما الذي يثبت دلالة استدعاء شخصية تراثية؟","correct":"تحليل الصور والموقف من نص العمل نفسه","writing":"بعد مراجعة النص المقرر بعنوان «أبو تمام - صلاح عبد الصبور» من مصدر معتمد، استخرج شاهدًا صحيحًا وحلله لغويًا أو سرديًا، ثم اكتب مثالًا من إنشائك وميّز بين المصدرين. إن لم يتوفر النص فاكتب فقط تحليل المثال المستقل دون نسبة أقوال إلى المؤلف.","wrong":["الاعتماد على العنوان وحده","اختلاق اقتباس ونسبته للمؤلف","إلغاء سياق النص ومصدره"]},{"cid":"c02be22c-60e1-4541-9365-ce42d62ab66b","uid":"2a01342e-f419-4f2a-a727-7dc0c1bd3e30","n":2,"title":"خطاب غير تاريخي - أمل دنقل","old":"DADYOOM_DZ_G12_LANGUAGES_OFFICIAL","focus":"مقارنة الخطاب الرمزي والسرد التاريخي","passage":"يحتاج نص أمل دنقل الصحيح لمعرفة معنى «غير تاريخي» ووظيفته في تشكيل الخطاب، ولا تُختلق فيه وقائع أو اقتباسات. مثال مستقل يتحدث فيه راو إلى شخصية تخيلية ليسائل قرارًا معاصرًا؛ السؤال الأدبي ليس وثيقة تاريخية.","question":"لماذا لا يعد الخطاب التخيلي سجلًا تاريخيًا؟","correct":"لأنه بناء فني يحتاج مصادر خارجية لتوثيق الوقائع","writing":"بعد مراجعة النص المقرر بعنوان «خطاب غير تاريخي - أمل دنقل» من مصدر معتمد، استخرج شاهدًا صحيحًا وحلله لغويًا أو سرديًا، ثم اكتب مثالًا من إنشائك وميّز بين المصدرين. إن لم يتوفر النص فاكتب فقط تحليل المثال المستقل دون نسبة أقوال إلى المؤلف.","wrong":["الاعتماد على العنوان وحده","اختلاق اقتباس ونسبته للمؤلف","إلغاء سياق النص ومصدره"]},{"cid":"c02be22c-60e1-4541-9365-ce42d62ab66b","uid":"d941ebb7-8c6b-47f2-b59d-5e4c5d956db2","n":1,"title":"في مدح الرسول - البوصيري","old":"DADYOOM_DZ_G12_LANGUAGES_OFFICIAL","focus":"التعامل الأمين مع المديح النبوي","passage":"تُحلل قصائد المديح النبوي من خلال النص الصحيح وإيقاعه وصوره ومقاصده، ولا يجوز تركيب أبيات ونسبتها إلى البوصيري أو ادعاء حديث نبوي غير مثبت. التمرين مستقل يطلب معرفة الفرق بين النص الشعري والخبر الديني الموثق.","question":"ما الواجب عند نقل بيت أو حديث في هذا السياق؟","correct":"التحقق من الأصل والنسبة والمصدر","writing":"بعد مراجعة النص المقرر بعنوان «في مدح الرسول - البوصيري» من مصدر معتمد، استخرج شاهدًا صحيحًا وحلله لغويًا أو سرديًا، ثم اكتب مثالًا من إنشائك وميّز بين المصدرين. إن لم يتوفر النص فاكتب فقط تحليل المثال المستقل دون نسبة أقوال إلى المؤلف.","wrong":["الاعتماد على العنوان وحده","اختلاق اقتباس ونسبته للمؤلف","إلغاء سياق النص ومصدره"]},{"cid":"c02be22c-60e1-4541-9365-ce42d62ab66b","uid":"d941ebb7-8c6b-47f2-b59d-5e4c5d956db2","n":2,"title":"في الزهد - ابن نباتة","old":"DADYOOM_DZ_G12_LANGUAGES_OFFICIAL","focus":"تمييز الوعظ الشعري من الدعوى التاريخية","passage":"يحتاج نص ابن نباتة المقرر إلى توثيق الأبيات وتحليل ألفاظ الموعظة والتذكير بأثر الأفعال دون تخمين سيرته الشخصية. في مثال مستقل يختار متعلم إهداء كتاب لمن يحتاجه بدل شرائه للزينة؛ ليس بيتًا تراثيًا.","question":"ما القيمة التي يعكسها النموذج المستقل؟","correct":"تقديم النفع على المباهاة","writing":"بعد مراجعة النص المقرر بعنوان «في الزهد - ابن نباتة» من مصدر معتمد، استخرج شاهدًا صحيحًا وحلله لغويًا أو سرديًا، ثم اكتب مثالًا من إنشائك وميّز بين المصدرين. إن لم يتوفر النص فاكتب فقط تحليل المثال المستقل دون نسبة أقوال إلى المؤلف.","wrong":["الاعتماد على العنوان وحده","اختلاق اقتباس ونسبته للمؤلف","إلغاء سياق النص ومصدره"]},{"cid":"c02be22c-60e1-4541-9365-ce42d62ab66b","uid":"cfe2b281-250c-4143-b451-ec694768e60b","n":1,"title":"آلام الاغتراب - البارودي","old":"DADYOOM_DZ_G12_LANGUAGES_OFFICIAL","focus":"تحليل الغربة دون اختلاق وقائع سيرة","passage":"يمكن أن يظهر المنفى في قصيدة من خلال صورة المكان والبعد والذكرى، لكن تفاصيل ما عاشه البارودي تحتاج مصادر سيرته وأبياته الصحيحة. مثال مستقل يقرأ فيه مسافر رسالة من أهله ويشتاق إلى بيت قديم.","question":"ما الذي يبيّن الشوق في المثال؟","correct":"الارتباط الوجداني برسالة الأهل","writing":"بعد مراجعة النص المقرر بعنوان «آلام الاغتراب - البارودي» من مصدر معتمد، استخرج شاهدًا صحيحًا وحلله لغويًا أو سرديًا، ثم اكتب مثالًا من إنشائك وميّز بين المصدرين. إن لم يتوفر النص فاكتب فقط تحليل المثال المستقل دون نسبة أقوال إلى المؤلف.","wrong":["الاعتماد على العنوان وحده","اختلاق اقتباس ونسبته للمؤلف","إلغاء سياق النص ومصدره"]},{"cid":"c02be22c-60e1-4541-9365-ce42d62ab66b","uid":"cfe2b281-250c-4143-b451-ec694768e60b","n":2,"title":"من وحي المنفى - أحمد شوقي","old":"DADYOOM_DZ_G12_LANGUAGES_OFFICIAL","focus":"الفصل بين تجربة المنفى والصورة الشعرية","passage":"عند تحليل شعر شوقي عن المنفى نرجع إلى الديوان والنص المدرسي لتحديد المخاطب والمكان والخيال قبل إصدار حكم. تدريب مستقل يصف شخصًا يشاهد صورة مدينته من بعيد دون نسب الكلمات إلى الشاعر.","question":"ما الخطوة اللازمة لفهم صورة المنفى؟","correct":"قراءة الأبيات وتوثيق السياق والمخاطب","writing":"بعد مراجعة النص المقرر بعنوان «من وحي المنفى - أحمد شوقي» من مصدر معتمد، استخرج شاهدًا صحيحًا وحلله لغويًا أو سرديًا، ثم اكتب مثالًا من إنشائك وميّز بين المصدرين. إن لم يتوفر النص فاكتب فقط تحليل المثال المستقل دون نسبة أقوال إلى المؤلف.","wrong":["الاعتماد على العنوان وحده","اختلاق اقتباس ونسبته للمؤلف","إلغاء سياق النص ومصدره"]},{"cid":"c02be22c-60e1-4541-9365-ce42d62ab66b","uid":"55ad738c-8248-4ab9-abc1-2c57a7167631","n":1,"title":"منشورات فدائية - نزار قباني","old":"DADYOOM_DZ_G12_LANGUAGES_OFFICIAL","focus":"تحديد الموقف والنداء الشعري دون تبني العنف","passage":"يدرس النص الصحيح من حيث المخاطب والرموز واللغة الحجاجية والسياق التاريخي، ولا تُنسب إلى نزار قباني جمل مصاغة هنا. مثال تدريبي يطالب متحدث بإتاحة الحقوق المدنية والحفاظ على كرامة الناس بأسلوب سلمي.","question":"ما معيار تحليل موقف المتكلم الشعري؟","correct":"الاستدلال بشواهد النص وسياقه","writing":"بعد مراجعة النص المقرر بعنوان «منشورات فدائية - نزار قباني» من مصدر معتمد، استخرج شاهدًا صحيحًا وحلله لغويًا أو سرديًا، ثم اكتب مثالًا من إنشائك وميّز بين المصدرين. إن لم يتوفر النص فاكتب فقط تحليل المثال المستقل دون نسبة أقوال إلى المؤلف.","wrong":["الاعتماد على العنوان وحده","اختلاق اقتباس ونسبته للمؤلف","إلغاء سياق النص ومصدره"]},{"cid":"c02be22c-60e1-4541-9365-ce42d62ab66b","uid":"55ad738c-8248-4ab9-abc1-2c57a7167631","n":2,"title":"حالة حصار - محمود درويش","old":"DADYOOM_DZ_G12_LANGUAGES_OFFICIAL","focus":"قراءة المكان والزمن وصوت المتكلم الشعري","passage":"لا يُعاد نشر أبيات «حالة حصار» ولا تُختلق صور منسوبة إلى محمود درويش؛ يستخلص المتعلم من النص المقرر علاقة اللغة بإحساس الحصار وصور اليومي، مع احترام السياق وتوثيق الشواهد.","question":"ما الذي يساعد على فهم دلالة الحصار شعريًا؟","correct":"المفردات والصور وصوت المتكلم في النص","writing":"بعد مراجعة النص المقرر بعنوان «حالة حصار - محمود درويش» من مصدر معتمد، استخرج شاهدًا صحيحًا وحلله لغويًا أو سرديًا، ثم اكتب مثالًا من إنشائك وميّز بين المصدرين. إن لم يتوفر النص فاكتب فقط تحليل المثال المستقل دون نسبة أقوال إلى المؤلف.","wrong":["الاعتماد على العنوان وحده","اختلاق اقتباس ونسبته للمؤلف","إلغاء سياق النص ومصدره"]},{"cid":"c02be22c-60e1-4541-9365-ce42d62ab66b","uid":"13bd79ec-185e-4e55-aa20-af05f1e3c83c","n":1,"title":"منزلة المثقفين في الأمة - محمد البشير الإبراهيمي","old":"DADYOOM_DZ_G12_LANGUAGES_OFFICIAL","focus":"تحديد الأطروحة ومسؤولية المثقف في المقال","passage":"يُراجع النص الصحيح لمحمد البشير الإبراهيمي لاستخراج دعواه وتعليلها وأسلوبه الحجاجي؛ لا يكفي عنوان المنزلة لاستنتاج الواجبات التي عددها الكاتب. مثال مستقل يناقش دور باحث في تصحيح معلومة منتشرة.","question":"ما الذي يجعل دور الباحث مسؤولًا في المثال؟","correct":"تصحيح الادعاء بالدليل ومصدره","writing":"بعد مراجعة النص المقرر بعنوان «منزلة المثقفين في الأمة - محمد البشير الإبراهيمي» من مصدر معتمد، استخرج شاهدًا صحيحًا وحلله لغويًا أو سرديًا، ثم اكتب مثالًا من إنشائك وميّز بين المصدرين. إن لم يتوفر النص فاكتب فقط تحليل المثال المستقل دون نسبة أقوال إلى المؤلف.","wrong":["الاعتماد على العنوان وحده","اختلاق اقتباس ونسبته للمؤلف","إلغاء سياق النص ومصدره"]},{"cid":"c02be22c-60e1-4541-9365-ce42d62ab66b","uid":"13bd79ec-185e-4e55-aa20-af05f1e3c83c","n":2,"title":"الصراع بين التقليد والتجديد في الأدب - طه حسين","old":"DADYOOM_DZ_G12_LANGUAGES_OFFICIAL","focus":"التحليل النقدي للحجة والرأي المقابل","passage":"يجب قراءة نص طه حسين الموثق للتمييز بين معنى التقليد والتجديد كما عرفهما الكاتب وبين موقفه من كل اتجاه، دون نسب رأي إليه من العنوان. مثال مستقل يناقش قارئ كيف يتغير أسلوب رواية مع بقاء عناصر سرد قديمة.","question":"كيف يقوّم القارئ حجة التجديد؟","correct":"يحدد التعريفات والشواهد والرد على الاعتراض","writing":"بعد مراجعة النص المقرر بعنوان «الصراع بين التقليد والتجديد في الأدب - طه حسين» من مصدر معتمد، استخرج شاهدًا صحيحًا وحلله لغويًا أو سرديًا، ثم اكتب مثالًا من إنشائك وميّز بين المصدرين. إن لم يتوفر النص فاكتب فقط تحليل المثال المستقل دون نسبة أقوال إلى المؤلف.","wrong":["الاعتماد على العنوان وحده","اختلاق اقتباس ونسبته للمؤلف","إلغاء سياق النص ومصدره"]}]'::jsonb)
    AS x(cid uuid,uid uuid,n integer,title text,old text,focus text,passage text,question text,correct text,writing text,wrong text[])
  LOOP
    SELECT l.id,l.content INTO STRICT target_lesson_id,prior_content
    FROM public.lessons l
    JOIN public.units u ON u.id=l.unit_id
    JOIN public.grades g ON g.id=u.grade_id
    JOIN public.curricula cu ON cu.id=g.curriculum_id
    JOIN public.countries co ON co.id=cu.country_id
    WHERE co.code='DZ' AND cu.id=r.cid AND g.grade_number=12 AND u.id=r.uid
      AND u.semester IS NULL AND l.sort_order=r.n AND l.title=r.title
      AND l.status='published'
    FOR UPDATE OF l;

    SELECT count(*) INTO checked FROM public.student_lesson_progress
      WHERE lesson_id=target_lesson_id;
    IF checked<>0 THEN RAISE EXCEPTION 'ALGERIA_G12_ACTIVE_PROGRESS_FOR_%',r.title; END IF;
    SELECT count(*) INTO checked FROM public.lesson_activity_attempts at
      JOIN public.lesson_activities a ON a.id=at.activity_id
      WHERE a.lesson_id=target_lesson_id;
    IF checked<>0 THEN RAISE EXCEPTION 'ALGERIA_G12_ACTIVE_ATTEMPTS_FOR_%',r.title; END IF;
    IF char_length(coalesce(prior_content,'')) >= 350 THEN
       RAISE EXCEPTION 'ALGERIA_G12_ALREADY_HAS_FULL_CONTENT_%',r.title;
    END IF;
    SELECT count(*) INTO existing FROM public.lesson_activities
       WHERE lesson_id=target_lesson_id AND content->>'origin'=r.old AND answer='{}'::jsonb;
    IF existing<>3 THEN
       RAISE EXCEPTION 'ALGERIA_G12_EXPECTED_3_ACTIVITY_PLACEHOLDERS_%_GOT_%',r.title,existing;
    END IF;

    UPDATE public.lessons SET
      content='ضاديوم — إثراء أصلي مستقل للسنة الثانية ثانوي في الجزائر. النص تدريبي غير منقول من الكتاب، وتظل مطابقة عنوان الدرس بالإصدار الوزاري معلقة.'
       ||E'\n\n'||'الموضوع: '||r.title
       ||E'\n\n'||'الهدف: '||r.focus||'.'
       ||E'\n\n'||'شرح وتطبيق غير منسوب: '||r.passage
       ||E'\n\n'||'استراتيجية القراءة: حدّد الفكرة المركزية، ثم استخرج قرينة من النص الذي تقرؤه بالفعل، وفسر أثر صياغتها، وبعد ذلك قارن بين تفسيرين في ضوء الدليل.'
       ||E'\n\n'||'تقويم فهم: '||r.question
       ||E'\n\n'||'نشاط تحليلي: '||r.writing
       ||E'\n\n'||'تمايز وتغذية راجعة: للمبتدئ مفردات مساعدة وأمثلة قصيرة؛ للمتوسط ترتيب شواهد ومناقشة أثرها؛ وللمتقدم نقد دليل مخالف وبناء استنتاج منصف. يحتاج الإنتاج الكتابي إلى مراجعة معلم، ولا تُنسب أمثلة ضاديوم إلى شعراء أو كتب وزارية.'
       ||E'\n\n'||'المحتوى السابق محفوظ: '||coalesce(prior_content,''),
       updated_at=now()
     WHERE id=target_lesson_id;

    UPDATE public.lesson_activities SET
      prompt='اقرأ المثال المستقل ثم حدد الفكرة الأساسية وقرينة لغوية تدعمها.',
      content=content||jsonb_build_object('origin','DADYOOM_DZ_G12_ORIGINAL_ENRICHMENT_36_20261009','previousOrigin',r.old,
        'text',r.passage,'notOfficialBook',true,'sourceVerification','pending')
    WHERE lesson_id=target_lesson_id AND activity_type='reading' AND content->>'origin'=r.old
      AND answer='{}'::jsonb;

    UPDATE public.lesson_activities SET prompt=r.question,
      content=content||jsonb_build_object('origin','DADYOOM_DZ_G12_ORIGINAL_ENRICHMENT_36_20261009','previousOrigin',r.old,
       'text',r.question,'notOfficialBook',true,'sourceVerification','pending',
       'options',CASE (r.n%4)
          WHEN 0 THEN jsonb_build_array(r.correct,r.wrong[1],r.wrong[2],r.wrong[3])
          WHEN 1 THEN jsonb_build_array(r.wrong[1],r.correct,r.wrong[2],r.wrong[3])
          WHEN 2 THEN jsonb_build_array(r.wrong[1],r.wrong[2],r.correct,r.wrong[3])
          ELSE jsonb_build_array(r.wrong[1],r.wrong[2],r.wrong[3],r.correct) END),
      answer=jsonb_build_object('correct',r.correct)
    WHERE lesson_id=target_lesson_id AND activity_type='multiple_choice'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

    UPDATE public.lesson_activities SET prompt=r.writing,
      content=content||jsonb_build_object('origin','DADYOOM_DZ_G12_ORIGINAL_ENRICHMENT_36_20261009','previousOrigin',r.old,
       'text',r.writing,'notOfficialBook',true,'sourceVerification','pending','humanReviewRequired',true)
    WHERE lesson_id=target_lesson_id AND activity_type='writing'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

    SELECT count(*) INTO existing FROM public.lesson_activities
      WHERE lesson_id=target_lesson_id AND content->>'origin'='DADYOOM_DZ_G12_ORIGINAL_ENRICHMENT_36_20261009';
    IF existing<>3 THEN
      RAISE EXCEPTION 'ALGERIA_G12_ACTIVITY_UPDATE_FAILED_%_COUNT_%',r.title,existing;
    END IF;
  END LOOP;
END
$dadyoom$;